            reject(new Error('Agent search operation timed out'))
          }, 300000)

          _staticSocketManager.emit('codx-junior-agent-search', {
            request: request,
            max_iterations: maxIterations
          }, (response) => {
            clearTimeout(timeoutId)
            if (response?.error) {
              reject(new Error(response.error))
            } else {
