  methods: {
    // Select the team addressed by the route (or panel) params, so the team
    // view is deep-linkable. No-op when no team id is present.
    applyRouteTeam(teamId = this.$route?.params?.teamId || this.params?.teamId) {
      if (!teamId) return
      const team = this.$storex.teams.teamById(teamId)
      if (!team) return
      this.$storex.teams.selectTeam(teamId)
      this.$storex.ui.setActiveTeam(team)
    },
    // Reflect the selected team in the URL so it survives a refresh.
    syncTeamRoute(team) {
      const teamId = this.$route?.params?.teamId
      if (!team?.id || teamId === team.id) return
      const projectName = this.$route?.params?.projectName
      if (projectName) {
        this.$router.replace({ name: 'team', params: { projectName, teamId: team.id } })
      } else {
        this.$router.replace({ name: 'team', params: { teamId: team.id } })
      }
    },
